<template>
  <div class="mobile-generated-list-container">

    <!-- 固定标题栏 -->
    <div class="generated-list-header">
      <div class="generated-list-header-title">
        {{ pageTitle }}
      </div>
    </div>
    
    <!-- Tab切换组件（条件显示） -->
    <mobile-tab 
      v-if="showTabs"
      :visible="showTabs"
      :active-tab="activeTab"
      :tabs="tabOptions"
      @tab-change="handleTabChange"
    />
    
    <!-- 无限滚动列表 -->
    <mobile-list-more
      :loading="loading"
      :finished="finished"
      :error="hasError"
      :distance="100"
      container-class="media-list-content"
      @load-more="loadMoreData"
      @retry="retryLoad"
    >
      <div class="media-grid">
        <div 
          v-for="item in mediaList" 
          :key="item.id"
          class="media-item"
          @click="handleItemClick(item)"
        >
          <!-- 图片项 -->
          <template v-if="item.mediaType === 'image'">
            <div class="image-item">
              <mobile-img
                :src="item.imageUrl" 
                w="100%"
                h="100%"
                fit="cover"
                class="media-image"
                @error="handleImageError"
              />
            </div>
          </template>
          
          <!-- 视频项 -->
          <template v-if="item.mediaType === 'video'">
            <div class="video-item">
              <l-video 
                :src="item.videoUrl" 
                w="100%" 
                h="100%" 
                fit="cover"
                :showControls="false"
                class="media-image"
                @load-success="() => handleVideoLoaded(item.id)"
                @load-error="(error) => handleVideoError(error, item.id)"
              />
              <!-- 只有当视频加载完成且主loading完成时才显示时长文本 -->
              <div 
                v-if="!loading && videoLoadStates[item.id]?.loaded && getVideoDuration(item)"
                class="time-text"
              >
                {{ getVideoDuration(item) }}
              </div>
            </div>
          </template>
        </div>
      </div>
    </mobile-list-more>
  </div>
</template>

<script setup>
import { ref, onMounted, computed, nextTick, reactive } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useI18n } from 'vue-i18n';
import MobileTab from '@/mobile/components/mobile-tab.vue';
import MobileListMore from '@/mobile/components/mobile-list-more.vue';
import MobileImg from '@/mobile/components/mobile-l-img.vue';
import LVideo from '@/mobile/components/mobile-l-video.vue';
import { ApiGeneration } from '@/api/api-generation';
import { GenerationType } from '@/types/enums';
import { useMediaListStore } from '@/store/modules/media-list';


// 常量定义
const PAGE_SIZE = 20;

// 多语言和路由
const { t } = useI18n();
const route = useRoute();
const router = useRouter();

// 媒体数据store
const mediaStore = useMediaListStore();

// 响应式数据
const loading = ref(false);
const finished = ref(false);
const currentPage = ref(1);
const activeTab = ref('all');
const mediaList = ref([]);
const errorMessage = ref('');
const hasError = ref(false);

// 视频加载状态追踪
const videoLoadStates = reactive({});

// Tab选项配置
const tabOptions = [
  { key: 'all', label: 'All' },
  { key: 'image', label: 'Image' },
  { key: 'video', label: 'Video' }
];

// 计算属性 - 路由配置
const routeConfig = computed(() => {
  switch (route.name) {
    case 'my-favorites':
      return {
        showTabs: true,
        pageTitle: t('myFavorites'),
        apiType: 'favorites'
      };
    case 'generated-images':
      return {
        showTabs: false,
        pageTitle: t('picturesIGenerated'),
        apiType: 'history',
        fixedMediaType: 'image'
      };
    case 'generated-videos':
      return {
        showTabs: false,
        pageTitle: t('videosIGenerated'),
        apiType: 'history',
        fixedMediaType: 'video'
      };
    default:
      return {
        showTabs: false,
        pageTitle: '',
        apiType: 'history'
      };
  }
});

// 计算属性 - 是否显示tabs
const showTabs = computed(() => routeConfig.value.showTabs);

// 计算属性 - 页面标题
const pageTitle = computed(() => routeConfig.value.pageTitle);

// Tab切换事件处理
const handleTabChange = (tabKey) => {
  console.log('Tab changed to:', tabKey);
  if (activeTab.value === tabKey) return;
  
  activeTab.value = tabKey;
  resetAndReload();
};

// 重置并重新加载数据
const resetAndReload = () => {
  currentPage.value = 1;
  mediaList.value = [];
  finished.value = false;
  errorMessage.value = '';
  hasError.value = false;
  
  // 清空视频加载状态
  Object.keys(videoLoadStates).forEach(key => {
    delete videoLoadStates[key];
  });
  
  nextTick(() => {
    loadMoreData();
  });
};

// 加载更多数据
const loadMoreData = async () => {
  if (loading.value || finished.value || hasError.value) return;
  
  try {
    loading.value = true;
    console.log('Loading data, page:', currentPage.value, 'tab:', activeTab.value);
    
    // 构建请求参数
    const params = {
      page: currentPage.value,
      page_size: PAGE_SIZE
    };
    
    // 根据路由和tab动态设置media_type
    if (routeConfig.value.fixedMediaType) {
      params.media_type = routeConfig.value.fixedMediaType;
    } else if (activeTab.value !== 'all') {
      params.media_type = activeTab.value;
    }
    
    console.log('Request params:', params);
    
    // 根据API类型调用不同接口
    const response = routeConfig.value.apiType === 'favorites'
      ? await ApiGeneration.getFavorites(params)
      : await ApiGeneration.getHistory(params);
    
    console.log('API Response:', response);
    
    // 检查响应状态
    if (response.code !== 200) {
      throw new Error(response.message || 'Failed to load data');
    }
    
    // 转换分页数据
    const paginationData = ApiGeneration.transformPaginationData(response);
    console.log('Pagination data:', paginationData);
    
    // 根据当前tab转换数据
    let transformedData = [];
    if (activeTab.value === 'video' || routeConfig.value.fixedMediaType === 'video') {
      transformedData = ApiGeneration.transformToVideoData(paginationData.items);
      // 为视频数据添加mediaType标识
      transformedData = transformedData.map(item => ({
        ...item,
        mediaType: 'video'
      }));
    } else if (activeTab.value === 'image' || routeConfig.value.fixedMediaType === 'image') {
      transformedData = ApiGeneration.transformToImageData(paginationData.items);
      // 为图片数据添加mediaType标识
      transformedData = transformedData.map(item => ({
        ...item,
        mediaType: 'image'
      }));
    } else {
      // all tab - 混合数据，保持接口原始顺序
      const allItems = paginationData.items;
      transformedData = allItems.map(item => {
        if (item.media_type === 'image') {
          // 处理图片项
          const [transformedImage] = ApiGeneration.transformToImageData([item]);
          return {
            ...transformedImage,
            mediaType: 'image'
          };
        } else if (item.media_type === 'video') {
          // 处理视频项
          const [transformedVideo] = ApiGeneration.transformToVideoData([item]);
          return {
            ...transformedVideo,
            mediaType: 'video'
          };
        } else {
          // 处理未知类型项目（备用）
          return {
            id: item.id || `unknown_${Date.now()}_${Math.random()}`,
            mediaType: 'unknown',
            originalApiData: item
          };
        }
      }).filter(item => item.mediaType !== 'unknown'); // 过滤掉未知类型
    }
    
    console.log('Transformed data:', transformedData);
    
    // 无限滚动数据合并
    if (currentPage.value === 1) {
      mediaList.value = transformedData;
    } else {
      mediaList.value.push(...transformedData);
    }
    
    // 更新分页状态
    currentPage.value++;
    
    // 判断是否还有更多数据
    if (transformedData.length < PAGE_SIZE || !paginationData.hasMore) {
      finished.value = true;
    }
    
  } catch (error) {
    console.error('Load data failed:', error);
    errorMessage.value = t('loadFailed');
    hasError.value = true;
    finished.value = true; // 阻止继续加载
  } finally {
    loading.value = false;
  }
};

// 重试加载
const retryLoad = () => {
  console.log('Retry loading triggered');
  errorMessage.value = '';
  hasError.value = false;
  loading.value = false;
  finished.value = false;
  
  // 重置到第一页重新加载
  currentPage.value = 1;
  
  nextTick(() => {
    loadMoreData();
  });
};

// 点击媒体项事件
const handleItemClick = (item) => {
  console.log('Media item clicked:', item);
  
  // 获取生成模式
  const generationMode = getGenerationMode(item);
  
  // 将数据保存到store，替代sessionStorage
  mediaStore.setCurrentMediaDetail(item, generationMode);
  
  // 导航到详情页面
  router.push({
    name: 'mobile-media-detail',
    params: {
      id: item.id
    },
    query: {
      type: item.mediaType || 'image',
      mode: generationMode
    }
  });
};

// 根据项目数据获取生成模式
const getGenerationMode = (item) => {
  // 优先根据原始API数据的generation_type判断
  const generationType = item.originalApiData?.generation_type || 
                        item.generationType || 
                        item.generation_type;
  
  if (generationType === 'image_to_video') {
    return GenerationType.IMAGE_TO_VIDEO;
  } else if (generationType === 'text_to_video') {
    return GenerationType.TEXT_TO_VIDEO;
  } else if (generationType === 'text_to_image') {
    return GenerationType.TEXT_TO_IMAGE;
  }
  
  // 根据媒体类型作为备用判断
  if (item.mediaType === 'image') {
    return GenerationType.TEXT_TO_IMAGE;
  } else if (item.mediaType === 'video') {
    return GenerationType.TEXT_TO_VIDEO; // 默认文生视频
  }
  
  return GenerationType.TEXT_TO_IMAGE;
};

// 图片加载错误处理
const handleImageError = (error) => {
  console.warn('Image load error:', error);
};

// 视频加载错误处理
const handleVideoError = (error, videoId) => {
  console.warn('Video load error:', error, 'videoId:', videoId);
  if (videoId) {
    videoLoadStates[videoId] = { loaded: false, error: true };
  }
};

// 视频加载成功处理
const handleVideoLoaded = (videoId) => {
  console.log('Video loaded successfully, videoId:', videoId);
  if (videoId) {
    videoLoadStates[videoId] = { loaded: true, error: false };
  }
};

// 获取视频时长
const getVideoDuration = (item) => {
  // 调试信息
  console.log('Getting video duration for item:', item.id, {
    originalApiData: item.originalApiData,
    mediaMetadata: item.originalApiData?.media_metadata,
    duration: item.originalApiData?.media_metadata?.duration,
    itemDuration: item.duration,
    videoConfig: item.videoConfig
  });

  // 优先从原始API数据获取
  const apiDuration = item.originalApiData?.media_metadata?.duration;
  if (apiDuration) {
    if (typeof apiDuration === 'string' && apiDuration.includes('s')) {
      return apiDuration;
    }
    if (typeof apiDuration === 'number') {
      return `${apiDuration}s`;
    }
  }

  // 备用：从转换后的数据获取
  if (item.videoConfig?.duration) {
    return item.videoConfig.duration;
  }
  
  // 备用：从item直接获取
  if (item.duration) {
    return item.duration;
  }

  return '';
};

// 初始化
onMounted(() => {
  console.log('Page mounted, route:', route.name);
  console.log('Route config:', routeConfig.value);
  
  // 根据路由设置初始tab
  if (routeConfig.value.fixedMediaType) {
    activeTab.value = routeConfig.value.fixedMediaType;
  }
  
  // 初始加载数据
  loadMoreData();
});
</script>

